CREATE OR REPLACE FUNCTION "public"."audit_trigger_fn"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
  BEGIN
    INSERT INTO public.audit_log (table_name, operation, record_id, old_data, new_data, changed_by)
    VALUES (
      TG_TABLE_NAME,
      TG_OP,
      CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END,
      CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE row_to_json(OLD)::JSONB END,
      CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE row_to_json(NEW)::JSONB END,
      auth.uid()
    );
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END;
  $$;


ALTER FUNCTION "public"."audit_trigger_fn"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."column_fill"("p_schema" "text", "p_table" "text") RETURNS TABLE("col" "text", "filled" bigint, "pct" numeric)
    LANGUAGE "plpgsql"
    AS $$
declare r record; n bigint; total bigint;
begin
  execute format('select count(*) from %I.%I', p_schema, p_table) into total;
  for r in
    select column_name from information_schema.columns
    where table_schema = p_schema and table_name = p_table
    order by ordinal_position
  loop
    execute format('select count(%I) from %I.%I', r.column_name, p_schema, p_table) into n;
    col := r.column_name; filled := n;
    pct := case when total = 0 then 0 else round(100.0 * n / total, 0) end;
    return next;
  end loop;
end $$;


ALTER FUNCTION "public"."column_fill"("p_schema" "text", "p_table" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_licenses_for_point"("lat" double precision, "lng" double precision) RETURNS TABLE("zone_id" "uuid", "zone_name" "text", "country" "text", "license_id" "uuid", "license_name" "text", "species" "text"[], "season_start" "date", "season_end" "date", "price_from" numeric, "currency" "text", "purchase_url" "text")
    LANGUAGE "sql"
    AS $$
  select
    lz.id,
    lz.name,
    lz.country,
    l.id,
    l.name,
    l.species,
    l.season_start,
    l.season_end,
    l.price_from,
    l.currency,
    l.purchase_url
  from license_zones lz
  join licenses l on l.zone_id = lz.id
  where st_contains(
    lz.boundary,
    st_setsrid(st_point(lng, lat), 4326)
  );
$$;


ALTER FUNCTION "public"."get_licenses_for_point"("lat" double precision, "lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO public.profiles (id, role, full_name)
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data ->> 'role', 'angler'),
    COALESCE(NEW.raw_user_meta_data ->> 'full_name', NEW.email)
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_license_zone"("p_name" "text", "p_country" "text", "p_region" "text", "p_river_system" "text", "p_geojson" "text", "p_source_url" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
declare
  new_id uuid;
begin
  insert into license_zones (name, country, region, river_system, boundary, source_url)
  values (
    p_name,
    p_country,
    p_region,
    p_river_system,
    st_multi(st_geomfromgeojson(p_geojson)),
    p_source_url
  )
  returning id into new_id;
  return new_id;
end;
$$;


ALTER FUNCTION "public"."import_license_zone"("p_name" "text", "p_country" "text", "p_region" "text", "p_river_system" "text", "p_geojson" "text", "p_source_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inquiries_advance_stage_reached"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  stages TEXT[] := ARRAY['inquiry', 'offer_sent', 'deposit_paid', 'completed'];
BEGIN
  IF array_position(stages, NEW.stage_reached) < array_position(stages, OLD.stage_reached) THEN
    NEW.stage_reached := OLD.stage_reached;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."inquiries_advance_stage_reached"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_trips_near"("lat" double precision, "lng" double precision, "radius_km" double precision DEFAULT 50, "filter_species" "text" DEFAULT NULL::"text", "filter_technique" "text" DEFAULT NULL::"text") RETURNS TABLE("trip_id" "uuid", "trip_title" "text", "guide_id" "uuid", "guide_name" "text", "location_name" "text", "distance_km" double precision, "price_from" numeric, "currency" "text", "species" "text"[], "techniques" "text"[])
    LANGUAGE "sql"
    AS $$
  select
    t.id,
    t.title,
    g.id,
    g.name,
    l.name,
    round((st_distance(
      l.geometry::geography,
      st_point(lng, lat)::geography
    ) / 1000)::numeric, 1),
    t.price_from,
    t.currency,
    t.species,
    t.techniques
  from trips t
  join locations l on t.location_id = l.id
  join guides g on t.guide_id = g.id
  where
    st_dwithin(
      l.geometry::geography,
      st_point(lng, lat)::geography,
      radius_km * 1000
    )
    and g.status = 'active'
    and t.status = 'active'
    and (filter_species is null or filter_species = any(t.species))
    and (filter_technique is null or filter_technique = any(t.techniques))
  order by st_distance(
    l.geometry::geography,
    st_point(lng, lat)::geography
  );
$$;


ALTER FUNCTION "public"."search_trips_near"("lat" double precision, "lng" double precision, "radius_km" double precision, "filter_species" "text", "filter_technique" "text") OWNER TO "postgres";


