CREATE OR REPLACE FUNCTION "public"."slugify"("txt" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select trim(both '-' from
    regexp_replace(lower(coalesce(txt,'')), '[^a-z0-9]+', '-', 'g'));
$$;


ALTER FUNCTION "public"."slugify"("txt" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_last_contact_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
     BEGIN
       UPDATE inquiries
       SET last_contact_at = (
         SELECT MAX(created_at)
         FROM lead_messages
         WHERE inquiry_id = NEW.inquiry_id
       )
       WHERE id = NEW.inquiry_id;
       RETURN NEW;
     END;
     $$;


ALTER FUNCTION "public"."sync_last_contact_at"() OWNER TO "postgres";


