CREATE TABLE IF NOT EXISTS "archive"."experience_availability_config" (
    "experience_id" "uuid" NOT NULL,
    "available_months" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "available_weekdays" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "advance_notice_hours" integer DEFAULT 48 NOT NULL,
    "max_advance_days" integer DEFAULT 180 NOT NULL,
    "slots_per_day" integer DEFAULT 1 NOT NULL,
    "start_time" time without time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "experience_availability_config_advance_notice_hours_check" CHECK (("advance_notice_hours" >= 0)),
    CONSTRAINT "experience_availability_config_max_advance_days_check" CHECK (("max_advance_days" >= 1)),
    CONSTRAINT "experience_availability_config_slots_per_day_check" CHECK (("slots_per_day" >= 1))
);


ALTER TABLE "archive"."experience_availability_config" OWNER TO "postgres";


COMMENT ON TABLE "archive"."experience_availability_config" IS 'Calendar rules for an experience: available months, weekdays, notice period and slots per day.';



COMMENT ON COLUMN "archive"."experience_availability_config"."available_months" IS 'Array of month numbers (1–12). Empty = experience runs year-round.';



COMMENT ON COLUMN "archive"."experience_availability_config"."available_weekdays" IS 'Array of weekday numbers (0=Sun … 6=Sat). Empty = available every weekday.';



COMMENT ON COLUMN "archive"."experience_availability_config"."advance_notice_hours" IS 'Minimum hours of advance notice required before the trip starts.';



COMMENT ON COLUMN "archive"."experience_availability_config"."max_advance_days" IS 'How many calendar days ahead the booking window is open.';



COMMENT ON COLUMN "archive"."experience_availability_config"."slots_per_day" IS 'Maximum number of bookings accepted on the same date (usually 1 for guided trips).';



