    "images" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "link_url" "text",
    CONSTRAINT "guide_accommodations_type_check" CHECK (("type" = ANY (ARRAY['cabin'::"text", 'hotel'::"text", 'hostel'::"text", 'lodge'::"text", 'apartment'::"text", 'other'::"text"])))
);


ALTER TABLE "archive"."guide_accommodations" OWNER TO "postgres";


