CREATE TABLE IF NOT EXISTS "public"."expedition_guides" (
    "expedition_id" "uuid" NOT NULL,
    "guide_id" "uuid" NOT NULL,
    "is_lead" boolean DEFAULT false NOT NULL,
    "rate_cents" bigint,
    "rate_unit" "text",
    "max_rods" integer,
    "licence_policy" "text",
    "gear_policy" "text",
    "pickup_from" "text",
    "includes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "excludes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "availability_confidence" "text" DEFAULT 'assumed'::"text" NOT NULL,
    "last_confirmed_at" "date",
    "internal_notes" "text",
