    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "expedition_guides_confidence_chk" CHECK (("availability_confidence" = ANY (ARRAY['confirmed'::"text", 'assumed'::"text", 'stale'::"text"]))),
    CONSTRAINT "expedition_guides_gear_chk" CHECK ((("gear_policy" IS NULL) OR ("gear_policy" = ANY (ARRAY['included'::"text", 'rental_extra'::"text", 'bring_own'::"text"])))),
    CONSTRAINT "expedition_guides_licence_chk" CHECK ((("licence_policy" IS NULL) OR ("licence_policy" = ANY (ARRAY['included'::"text", 'client_pays'::"text", 'varies'::"text"])))),
    CONSTRAINT "expedition_guides_rate_unit_chk" CHECK ((("rate_unit" IS NULL) OR ("rate_unit" = ANY (ARRAY['party_day'::"text", 'rod_day'::"text", 'package'::"text", 'quote'::"text"]))))
);


ALTER TABLE "public"."expedition_guides" OWNER TO "postgres";


