    "internal_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "expedition_waters_public_requires_confirmation" CHECK ((("is_public" = false) OR (("source" = 'guide_confirmed'::"text") AND ("confirmed_by_guide_id" IS NOT NULL)))),
    CONSTRAINT "expedition_waters_source_chk" CHECK (("source" = ANY (ARRAY['guide_confirmed'::"text", 'guide_website'::"text", 'inferred'::"text"])))
);


