    "centroid_lng" numeric(9,6),
    "internal_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "waters_access_chk" CHECK (("access_type" = ANY (ARRAY['open_permit'::"text", 'allocated'::"text", 'lodge_partner'::"text", 'unknown'::"text"]))),
    CONSTRAINT "waters_type_chk" CHECK ((("water_type" IS NULL) OR ("water_type" = ANY (ARRAY['river'::"text", 'lake'::"text", 'spring_creek'::"text", 'beat'::"text", 'coast'::"text", 'highland'::"text"]))))
);


ALTER TABLE "public"."waters" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."expedition_waters_public" AS
 SELECT "ew"."expedition_id",
    "w"."id" AS "water_id",
    "w"."name",
    "w"."name_local",
    "w"."water_type",
    "w"."region_id",
    "ew"."is_primary",
    "ew"."months"
   FROM ("public"."expedition_waters" "ew"
     JOIN "public"."waters" "w" ON (("w"."id" = "ew"."water_id")))
  WHERE (("ew"."is_public" = true) AND ("ew"."source" = 'guide_confirmed'::"text"));


ALTER VIEW "public"."expedition_waters_public" OWNER TO "postgres";


COMMENT ON VIEW "public"."expedition_waters_public" IS 'Site-facing water list. Excludes internal_notes, access_type, coordinates, and anything not confirmed directly by a guide.';



