    "youtube_url" "text",
    "status" "public"."guide_status" DEFAULT 'pending'::"public"."guide_status" NOT NULL,
    "pricing_model" "public"."pricing_model" DEFAULT 'commission'::"public"."pricing_model" NOT NULL,
    "stripe_account_id" "text",
    "stripe_charges_enabled" boolean DEFAULT false NOT NULL,
    "stripe_payouts_enabled" boolean DEFAULT false NOT NULL,
    "verified_at" timestamp with time zone,
    "average_rating" numeric(3,2),
    "total_reviews" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_beta_listing" boolean DEFAULT false NOT NULL,
    "invite_email" "text",
    "slug" "text",
    "tagline" "text",
    "specialties" "text"[],
    "google_rating" numeric(3,1),
    "google_review_count" integer,
    "google_profile_url" "text",
    "external_reviews" "jsonb",
    "cancellation_policy" "text" DEFAULT 'moderate'::"text" NOT NULL,
    "boat_name" "text",
    "boat_type" "text",
    "boat_length_m" numeric(4,1),
    "boat_engine" "text",
    "boat_capacity" integer,
    "landscape_url" "text",
    "website_url" "text",
    "facebook_url" "text",
    "calendar_mode" "text" DEFAULT 'per_listing'::"text" NOT NULL,
    "calendar_disabled" boolean DEFAULT false NOT NULL,
    "default_balance_payment_method" "text" DEFAULT 'cash'::"text" NOT NULL,
    "accepted_payment_methods" "text"[] DEFAULT ARRAY['cash'::"text", 'online'::"text"],
    "commission_rate" numeric(5,4) DEFAULT 0.10 NOT NULL,
    "founding_guide_until" "date",
    "photo_marketing_consent" boolean DEFAULT false NOT NULL,
    "is_hidden" boolean DEFAULT false NOT NULL,
    "iban" "text",
    "iban_holder_name" "text",
    "iban_bic" "text",
    "iban_bank_name" "text",
    "terms_accepted_at" timestamp with time zone,
    "payment_ready" boolean GENERATED ALWAYS AS (((("stripe_account_id" IS NOT NULL) AND ("stripe_charges_enabled" = true) AND ("stripe_payouts_enabled" = true)) OR (("iban" IS NOT NULL) AND ("iban" <> ''::"text")))) STORED,
    CONSTRAINT "guides_accepted_payment_methods_check" CHECK ((("accepted_payment_methods" IS NULL) OR (("array_length"("accepted_payment_methods", 1) > 0) AND ("accepted_payment_methods" <@ ARRAY['cash'::"text", 'online'::"text"])))),
    CONSTRAINT "guides_average_rating_check" CHECK ((("average_rating" >= (0)::numeric) AND ("average_rating" <= (5)::numeric))),
    CONSTRAINT "guides_boat_capacity_pos" CHECK ((("boat_capacity" IS NULL) OR ("boat_capacity" > 0))),
    CONSTRAINT "guides_boat_length_pos" CHECK ((("boat_length_m" IS NULL) OR ("boat_length_m" > (0)::numeric))),
    CONSTRAINT "guides_boat_type_values" CHECK ((("boat_type" IS NULL) OR ("boat_type" = ANY (ARRAY['center_console'::"text", 'cabin'::"text", 'rib'::"text", 'drift_boat'::"text", 'kayak'::"text"])))),
    CONSTRAINT "guides_calendar_mode_values" CHECK (("calendar_mode" = ANY (ARRAY['per_listing'::"text", 'shared'::"text"]))),
    CONSTRAINT "guides_cancellation_policy_values" CHECK (("cancellation_policy" = ANY (ARRAY['flexible'::"text", 'moderate'::"text", 'strict'::"text"]))),
    CONSTRAINT "guides_default_balance_payment_method_check" CHECK (("default_balance_payment_method" = ANY (ARRAY['stripe'::"text", 'cash'::"text"]))),
    CONSTRAINT "guides_google_rating_range" CHECK ((("google_rating" IS NULL) OR (("google_rating" >= 1.0) AND ("google_rating" <= 5.0)))),
    CONSTRAINT "guides_google_review_count_nonneg" CHECK ((("google_review_count" IS NULL) OR ("google_review_count" >= 0))),
    CONSTRAINT "guides_tagline_max_length" CHECK ((("tagline" IS NULL) OR ("char_length"("tagline") <= 120))),
    CONSTRAINT "guides_years_experience_check" CHECK (("years_experience" >= 0))
);


ALTER TABLE "public"."guides" OWNER TO "postgres";


COMMENT ON TABLE "public"."guides" IS 'Guide profiles. status=active means the guide is publicly visible.';



COMMENT ON COLUMN "public"."guides"."pricing_model" IS 'flat_fee = €29/month subscription; commission = 10% per booking, no monthly fee.';



COMMENT ON COLUMN "public"."guides"."is_beta_listing" IS 'TRUE for admin-created preview listings that have no linked auth user.
   These appear on the public site but the guide has no dashboard access.';



COMMENT ON COLUMN "public"."guides"."calendar_disabled" IS 'When true, trip pages show inquiry-only CTA regardless of experience booking_type.';



COMMENT ON COLUMN "public"."guides"."iban" IS 'IBAN for direct angler→guide payment in manual payment model';



COMMENT ON COLUMN "public"."guides"."iban_holder_name" IS 'Account holder name shown to angler for manual transfers';



COMMENT ON COLUMN "public"."guides"."iban_bic" IS 'BIC/SWIFT code for the IBAN';



COMMENT ON COLUMN "public"."guides"."iban_bank_name" IS 'Optional bank name shown to angler for clarity';



COMMENT ON COLUMN "public"."guides"."payment_ready" IS 'Auto-computed. true = guide has active Stripe Connect OR saved IBAN. Never write directly.';



CREATE TABLE IF NOT EXISTS "public"."inquiries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "trip_id" "uuid",
    "guide_id" "uuid",
    "angler_name" "text" NOT NULL,
    "angler_email" "text" NOT NULL,
    "angler_country" "text",
    "requested_dates" "text"[],
    "party_size" integer DEFAULT 1 NOT NULL,
    "message" "text",
    "status" "text" DEFAULT 'pending_fa_review'::"text" NOT NULL,
    "fa_notes" "text",
