    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "selected_option" "text",
    "offer_total_eur" numeric,
    "offer_deposit_eur" numeric,
    "offer_notes" "text",
    "offer_sent_at" timestamp with time zone,
    "offer_trip_plan" "text",
    "offer_license_info" "text",
    "offer_inclusions" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "offer_questions" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "offer_answers" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "offer_refund_reason" "text",
    "offer_token" "text",
    "offer_token_expires_at" timestamp with time zone,
    "offer_photos" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "offer_location" "text",
    "offer_what_to_bring" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "offer_schedule" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "offer_license_heading" "text",
    "offer_location_lat" numeric,
    "offer_location_lng" numeric,
    "offer_location_zoom" integer DEFAULT 10,
    "offer_location_geojson" "jsonb",
    "angler_phone" "text",
    "experience_page_id" "uuid",
    "internal_deal_total_eur" numeric,
    "internal_commission_eur" numeric,
    "internal_notes" "text",
    "lost_reason" "text",
    "last_contact_at" timestamp with time zone,
    "next_action" "text",
    "deal_currency" "text" DEFAULT 'EUR'::"text" NOT NULL,
    "assigned_guide_id" "uuid",
    "assigned_at" timestamp with time zone,
    "guide_acceptance" "text",
    "guide_decline_reason" "text",
    "guide_responded_at" timestamp with time zone,
    "guide_offer_eta" "text",
    "external_offer_sent" boolean DEFAULT false NOT NULL,
    "agent_status" "text",
    "agent_round" smallint DEFAULT 0 NOT NULL,
    "offer_options" "jsonb",
    "selected_option_id" "text",
    "trip_country" "text",
    "trip_type" "text",
    "priority" "text",
    "email_thread_message_id" "text",
    "stage_reached" "text" DEFAULT 'inquiry'::"text" NOT NULL,
    "trip_length" "text",
    "gclid" "text",
    CONSTRAINT "inquiries_agent_status_check" CHECK (("agent_status" = ANY (ARRAY['waiting'::"text", 'ready'::"text", 'stopped'::"text"]))),
    CONSTRAINT "inquiries_deal_currency_check" CHECK (("deal_currency" = ANY (ARRAY['EUR'::"text", 'USD'::"text"]))),
    CONSTRAINT "inquiries_guide_acceptance_check" CHECK (("guide_acceptance" = ANY (ARRAY['accepted'::"text", 'declined'::"text"]))),
    CONSTRAINT "inquiries_priority_check" CHECK (("priority" = ANY (ARRAY['high'::"text", 'medium'::"text", 'low'::"text", 'not_viable'::"text"]))),
    CONSTRAINT "inquiries_stage_reached_check" CHECK (("stage_reached" = ANY (ARRAY['inquiry'::"text", 'offer_sent'::"text", 'deposit_paid'::"text", 'completed'::"text"]))),
    CONSTRAINT "inquiries_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'in_negotiation'::"text", 'waiting_for_guide_offer'::"text", 'offer_sent'::"text", 'waiting_for_deposit'::"text", 'deposit_sent'::"text", 'deposit_paid'::"text", 'completed'::"text", 'lost'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "inquiries_trip_length_check" CHECK (("trip_length" = ANY (ARRAY['1'::"text", '2-3'::"text", '4-7'::"text", '7+'::"text"]))),
    CONSTRAINT "inquiries_trip_type_check" CHECK (("trip_type" = ANY (ARRAY['day_trip'::"text", 'multi_day'::"text", 'lake_guiding'::"text", 'unknown'::"text"])))
);


