CREATE POLICY "guide_images_admin_write" ON "public"."guide_images" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"text"))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role" = 'admin'::"text")))));



CREATE POLICY "guide_images_owner_write" ON "public"."guide_images" TO "authenticated" USING (("guide_id" = ( SELECT "guides"."id"
   FROM "public"."guides"
  WHERE ("guides"."user_id" = "auth"."uid"())
 LIMIT 1))) WITH CHECK (("guide_id" = ( SELECT "guides"."id"
   FROM "public"."guides"
  WHERE ("guides"."user_id" = "auth"."uid"())
 LIMIT 1)));



