-- -----------------------------------------------------------------------------
-- B. Auth trigger (auth schema excluded from db dump by default)
-- Trigger on auth.users → public.handle_new_user() already exists on prod.
-- Included here so the shadow DB matches production for db diff.
-- -----------------------------------------------------------------------------

CREATE OR REPLACE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- -----------------------------------------------------------------------------
-- C. Storage policies (storage schema excluded from db dump by default)
-- 19 policies on storage.objects; 7 buckets confirmed via SELECT on prod.
-- Buckets (public=true): expedition-photos, guide-intake-photos, guide-photos,
--   landscapes, offer-photos, review-media, videos.
-- -----------------------------------------------------------------------------

create policy "Admin deletes guide photos"
  on "storage"."objects"
  as permissive
  for delete
  to public
  using (((bucket_id = 'guide-photos'::text) AND (EXISTS ( SELECT 1
     FROM public.profiles
    WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::text))))));

create policy "Admin updates guide photos"
  on "storage"."objects"
  as permissive
  for update
  to public
  using (((bucket_id = 'guide-photos'::text) AND (EXISTS ( SELECT 1
     FROM public.profiles
    WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::text))))));

create policy "Admin upload videos"
  on "storage"."objects"
  as permissive
  for insert
  to public
  with check (((bucket_id = 'videos'::text) AND (EXISTS ( SELECT 1
     FROM public.profiles
    WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::text))))));

create policy "Admin uploads guide photos"
  on "storage"."objects"
  as permissive
  for insert
  to public
  with check (((bucket_id = 'guide-photos'::text) AND (EXISTS ( SELECT 1
     FROM public.profiles
    WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::text))))));

create policy "Authenticated users upload guide photos"
  on "storage"."objects"
  as permissive
  for insert
  to public
  with check (((bucket_id = 'guide-photos'::text) AND (auth.role() = 'authenticated'::text)));

create policy "File owner deletes own guide photos"
  on "storage"."objects"
  as permissive
  for delete
  to public
  using (((bucket_id = 'guide-photos'::text) AND ((owner)::text = (auth.uid())::text)));

create policy "File owner updates own guide photos"
  on "storage"."objects"
  as permissive
  for update
  to public
  using (((bucket_id = 'guide-photos'::text) AND ((owner)::text = (auth.uid())::text)));

create policy "Public read guide photos"
  on "storage"."objects"
  as permissive
  for select
  to public
  using ((bucket_id = 'guide-photos'::text));

create policy "Public read videos"
  on "storage"."objects"
  as permissive
  for select
  to public
  using ((bucket_id = 'videos'::text));

create policy "guide-photos authenticated update"
  on "storage"."objects"
  as permissive
  for update
  to authenticated
  using ((bucket_id = 'guide-photos'::text));

create policy "guide-photos authenticated upload"
  on "storage"."objects"
  as permissive
  for insert
  to authenticated
  with check ((bucket_id = 'guide-photos'::text));

create policy "guide-photos owner delete"
  on "storage"."objects"
  as permissive
  for delete
  to authenticated
  using (((bucket_id = 'guide-photos'::text) AND ((storage.foldername(name))[1] = ( SELECT (guides.id)::text AS id
     FROM public.guides
    WHERE (guides.user_id = auth.uid())
   LIMIT 1))));

create policy "guide-photos public read"
  on "storage"."objects"
  as permissive
  for select
  to public
  using ((bucket_id = 'guide-photos'::text));

create policy "guides delete offer photos"
  on "storage"."objects"
  as permissive
  for delete
  to authenticated
